theory.predict_source:
def predict(parameters, state, history):
    import numpy as np

    pref = int(parameters["preferred_option"])
    n_opts = np.asarray(state).shape[0]

    probs = np.zeros(n_opts)
    if pref < n_opts:
        probs[pref] = 1.0
    else:
        probs[0] = 1.0

    return probs

